import 'package:flat_buffers/flat_buffers.dart';

void main() {
  final builder = Builder(initialSize: 1024);
  // Example: write a string
  final offset = builder.writeString('Hello FlatBuffers');
  builder.finish(offset);
  final bytes = builder.buffer;
  // Read back
  final bb = ByteData.sublistView(bytes);
  final reader = ByteDataReader(bb);
  final str = reader.readString(offset);
  print(str);
}
